</template>

<script setup>
import { onMounted, ref } from 'vue';
import { getParentDashboard, parentLogin } from '../api';
import HelpGuide from '../components/HelpGuide.vue';

const tokenKey = 'parent_portal_token';
const token = ref(localStorage.getItem(tokenKey) || '');
const loginForm = ref({
  StudentID: 0,
  Phone: ''
});
const loginError = ref('');
const dashboard = ref(null);

const loadDashboard = async () => {
  if (!token.value) return;
  dashboard.value = await getParentDashboard(token.value);
};

const login = async () => {
  loginError.value = '';
  try {
    const result = await parentLogin(loginForm.value);
    token.value = result.token;
    localStorage.setItem(tokenKey, result.token);
    await loadDashboard();
  } catch (error) {
    loginError.value = '登入失敗 (Login failed)';
  }
};

const logout = () => {
  token.value = '';
  localStorage.removeItem(tokenKey);
  dashboard.value = null;
};

onMounted(() => {
  loadDashboard();
});
</script>
