## 3. `/home/admin/backend/app/Http/Controllers/ProfileController.php`

```php
<?php

namespace App\Http\Controllers;

use App\Models\User;
use App\Models\UserCampus;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class ProfileController extends Controller
{
    /**
     * GET /api/v1/profiles
     * Returns teachers/directors visible to the authenticated user's campus.
     */
    public function index(Request $request)
    {
        $role = $request->attributes->get('auth_role');
        $campusIds = $role === 'super_admin' ? [] : $request->attributes->get('auth_campus_ids', []);

        $query = User::query()->whereIn('type', ['T', 'D', 'S']);

        // Filter by single id (used by App.vue fetchProfile)
        if ($request->filled('id')) {
            $query->where('id', (int) $request->input('id'));
        }

        // Filter by campus: only show users linked to the same campus
        if (!empty($campusIds) && !$request->filled('id')) {
            $query->whereIn('id', function ($sub) use ($campusIds) {
                $sub->select('UserID')
                    ->from('UserCampus')
                    ->whereIn('CampusID', $campusIds);
            });
        }

        if ($request->filled('username__ilike')) {
            $query->where('Name', 'like', '%' . $request->input('username__ilike') . '%');
        }

        // Filter by role (teacher/director/super_admin) — maps to type column
        if ($request->filled('role')) {
            $roleMap = ['teacher' => 'T', 'director' => 'D', 'super_admin' => 'S'];
            $typeFilter = $roleMap[$request->input('role')] ?? null;
            if ($typeFilter) {
                $query->where('type', $typeFilter);
            }
        }

        $isSingle = $request->boolean('single');
        $perPage  = $request->input('per_page');

        // Pre-load branch assignments for all users
        $allCampusRows = DB::table('UserCampus')->get()->groupBy('UserID');

        $transform = function ($user) use ($allCampusRows) {
            $user->username = $user->Name;
            $user->role = match ($user->type) {
                'S' => 'super_admin',
                'T' => 'teacher',
                default => 'director',
            };
            // Include primary branch_id (first UserCampus entry)
            $campusRows = $allCampusRows->get($user->id, collect());
            $user->branch_id = $campusRows->isNotEmpty() ? (int) $campusRows->first()->CampusID : null;
            $user->branch_ids = $campusRows->pluck('CampusID')->map(fn($id) => (int)$id)->values()->all();
            $user->status = 'active'; // Default; can be extended with a status column
            return $user;
        };

        // .single() — return one object directly
        if ($isSingle) {
            $user = $query->first();
            if (!$user) return response()->json(['error' => ['message' => 'Not found']], 404);
            return response()->json($transform($user));
        }

        if ($perPage === 'all') {
            $users = $query->get();
            $users->transform($transform);
        } else {
            $users = $query->paginate(min((int) ($perPage ?? 50), 200));
            $users->getCollection()->transform($transform);
        }

        return response()->json($perPage === 'all' ? $users : $users);
    }

    public function store(Request $request)
    {
        $data = $request->validate([
            'name'      => 'required|string|max:64',
            'email'     => 'required|string|max:128',
            'password'  => 'required|string|min:4|max:128',
            'role'      => 'nullable|string|in:teacher,director',
            'campus_id' => 'nullable|integer',
        ]);

        $exists = User::where('LoginName', $data['email'])->exists();
        if ($exists) {
            return response()->json(['message' => '此帳號已存在'], 409);
        }

        $type = match ($data['role'] ?? 'teacher') {
            'director' => 'D',
            default    => 'T',
        };

        $user = User::create([
            'LoginName' => $data['email'],
            'Name'      => $data['name'],
            'PSW'       => password_hash($data['password'], PASSWORD_DEFAULT),
            'type'      => $type,
        ]);

        // Link to campus if provided
        $campusId = $data['campus_id'] ?? null;
        if (!$campusId) {
            $campusIds = $request->attributes->get('auth_campus_ids', []);
            $campusId = $campusIds[0] ?? null;
        }
        if ($campusId) {
            UserCampus::firstOrCreate([
                'UserID'   => $user->id,
                'CampusID' => $campusId,
            ], ['Approved' => true]);
        }

        // Auto-create Teacher row
        if ($type === 'T' && !DB::table('Teacher')->where('id', $user->id)->exists()) {
            DB::table('Teacher')->insert([
                'id'        => $user->id,
                'T_Name'    => $user->Name,
                'CampusID'  => $campusId ?? 0,
                'Enable'    => 1,
                'MDT'       => now(),
                'TelegramID' => '',
            ]);
        }

        $user->username = $user->Name;
        return response()->json($user, 201);
    }

    public function update(Request $request, $id)
    {
        $user = User::findOrFail($id);

        $data = $request->validate([
            'name'     => 'nullable|string|max:64',
            'password' => 'nullable|string|min:4|max:128',
        ]);

        if (!empty($data['name'])) {
            $user->Name = $data['name'];
            DB::table('Teacher')->where('id', $user->id)->update(['T_Name' => $data['name']]);
        }
        if (!empty($data['password'])) {
            $user->PSW = password_hash($data['password'], PASSWORD_DEFAULT);
        }
        $user->save();

        $user->username = $user->Name;
        return response()->json($user);
    }
}
